const body = $input.first().json.body;
const query = $input.first().json.query;
const payload = body.payload;
const evento_uri = payload.scheduled_event?.uri || payload.event || '';
const evento_uuid = evento_uri.split('/').pop() || '';

const nombre_lead = payload.name || 'Sin nombre';
const email_lead = payload.email || '';
const nombre_evento = 'Valoracion Gratuita';
const clinica_id = query?.clinica_id || 'desconocida';

const schema_name = (clinica_id || 'clinica_demo')
  .replace(/-/g, '_')
  .replace(/[^a-zA-Z0-9_]/g, '')
  .toLowerCase();

const fecha_cita = payload.scheduled_event?.start_time || '';

const fecha_formateada = fecha_cita 
  ? new Date(fecha_cita).toLocaleString('es-CO', {
      timeZone: 'America/Bogota',
      weekday: 'long',
      day: 'numeric',
      month: 'long',
      hour: '2-digit',
      minute: '2-digit'
    })
  : 'fecha por confirmar';

return [{
  json: {
    nombre_lead,
    email_lead,
    fecha_cita,
    fecha_formateada,
    nombre_evento,
    evento_uuid,
    clinica_id,
    schema_name
  }
}];

