// Determinar de dónde vienen los datos del lead
// Si se encontró por email, viene de "Buscar lead por email"
// Si se encontró por UUID, viene de "Buscar lead por UUID" (y ya se actualizó el email)

const datos_calendly = $('Extraer datos de Calendly').first().json;

// El Merge pasa los datos del lead encontrado (por cualquiera de las dos vías)
const lead = $input.first().json;

return [{
  json: {
    // Datos del lead
    numero: lead.numero,
    nombre: lead.nombre,
    clinica_id: lead.clinica_id,
    email: datos_calendly.email_lead, // siempre usar el email de Calendly (puede ser el actualizado)
    estado: lead.estado,

    // Datos de Calendly
    nombre_lead: datos_calendly.nombre_lead,
    email_lead: datos_calendly.email_lead,
    fecha_cita: datos_calendly.fecha_cita,
    fecha_formateada: datos_calendly.fecha_formateada,
    evento_uuid: datos_calendly.evento_uuid
  }
}];

